def create():
    db = reconstruct()
    try:
        for u in LESSONS:
            row = db.execute('SELECT * FROM lessons WHERE seed_key=?', (u['seed_key'],)).fetchone()
            if row is None:
                raise ValueError('Missing seed ' + u['seed_key'])
            bundle = build_from_spec(baseline_data(row), u, VISUALS[u['seed_key']])
            out = ROOT / 'lesson-pipeline/authored' / f"{u['seed_key']}.json"
            atomic_json(out, bundle)
            print('Written Core bundle:', out)
    finally:
        db.close()


if __name__ == '__main__':
    create()
